// RunCloser runs every check — generated and yours — against every
// harness.
//
//	RunCloser(t,
//		CloserHarness[*InMemory]{Name: "in-memory", New: NewInMemory},
//		CloserSuite.Without(CloserSuite.Checks.Close.Smoke()),
//	)
func RunCloser(
	t *testing.T, opts ...CloserRunOpt,
) {
	t.Helper()
	var rc closerRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := closerNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	// Between folding and running: a misused run reports every fix it
	// needs and executes nothing, rather than reporting one and leaving
	// the rest to be found a cycle at a time.
	rc.Fail(t, "RunCloser")
	suite.Run(t,
		closerSuite().With(rc.Extra...).Without(rc.Drops...),
		rc.Subjects...)
}

// ProveCloser drives each of your rows against the defect it names.
//
// A row with no ProvenBy is not skipped — it is held to saying why
// through Argued. The parity gate refuses a Proven claim with no
// evidence and evidence for a claim nobody made, in both directions, so
// this is where "proven able to fail" stops being prose.
func ProveCloser(
	t *testing.T, checks CloserChecks,
) {
	t.Helper()
	// The RUN's config, not the derived one: a check proven at default
	// pools carries no evidence about the pools a run actually uses.
	fx := closerNewFixture()
	bound := make([]suite.Check[Closer], 0, len(checks))
	defects := prove.Defects[Closer]{}
	for _, row := range checks {
		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveCloser: %v", err)
		}
		bound = append(bound, bd)
		if row.ProvenBy == nil {
			continue
		}
		sub, err := row.ProvenBy.Subject()
		if err != nil {
			t.Fatalf("ProveCloser: check %q: defect: %v", bd.ID, err)
		}
		defects[bd.ID] = prove.Defect[Closer]{
			Subject: sub, Reason: row.ProvenReason,
		}
	}
	prove.All(t, bound, defects)
}

